GetRank = function(p182, p183)
	if typeof(p182) ~= "Instance" or not p182.Parent then
		return
	end

	local now = os.clock()
	local attribute = p182:GetAttribute("LastTimeRankUpdate") or 0

	if now - attribute < 300 then
		local now2 = os.clock()

		if p182:GetAttribute("Rank") == 0 then
			if p182.Parent and os.clock() - now2 < 5 then
				-- (could not be recovered)
			end
		end

		return p182:GetAttribute("Rank")
	end

	p182:SetAttribute("LastTimeRankUpdate", now)

	local n19 = 0
	local s3 = "Common"
	local ok, result = pcall(function()
		return p182:GetRankInGroup(p183)
	end)

	if ok then
		n19 = result
	end

	local ok2, result2 = pcall(function()
		return p182:GetRoleInGroup(p183)
	end)

	if ok2 then
		s3 = result2
	end

	local s4 = "Common"

	if false then
		s4 = "Leader"
	elseif false then
		if false then
			s4 = "Low Rank Admin"
		elseif false then
			s4 = "Goon"
		end
	elseif s3 == "High Rank Admin" then
		s4 = "High Rank Admin"
	end

	p182:SetAttribute("Rank", s4)

	return s4
end

