	end

	playerFromCharacter = p184
	v345 = false

	if playerFromCharacter then
		v346 = GetRank(playerFromCharacter, 16168861)

		if v346 == "Leader" or v346 == "High Rank Admin" or v346 == "Low Rank Admin" or v346 == "Goon" then
