RegisterGrabSpam = function(p381, p382)
	local v485 = GrabSpamKinds[p382]

	if not _G[v485.Enabled] or p381 == LocalPlayer.Name then
		return
	end

	local v486 = PS:FindFirstChild(p381)

	if not v486 or GrabSpamPunishing[v486] then
		return
	end

	local now = os.clock()
	local v488 = GrabSpamLog[p382][p381] or {}

	GrabSpamLog[p382][p381] = v488

	for i = #v488, 1, -1 do
		if now - v488[i] > 3 then
			table.remove(v488, i)
		end
	end

	table.insert(v488, now)

	if (_G[v485.Grabs] or 5) <= #v488 then
		table.clear(v488)
		StartGrabSpamPunishment(v486, p382)
	end
