read_cmds = function(p450, p451)
	if type(p450) == "string" and type(p451) == "string" then
		local t34 = {
			Message = p450,
			FromSpeaker = PS:FindFirstChild(p451)
		}
		local v963 = string.find(t34.Message, ":")
		local FromSpeaker, v966

		if v963 then
			t34.Message = string.sub(t34.Message, v963, t34.Message:len())
			FromSpeaker = t34.FromSpeaker

			if FromSpeaker then
				v966 = GetRank(FromSpeaker, 16168861)

				if v966 == "Leader" then
					Execute_Commands(t34.Message, "Leader", FromSpeaker.Name, v966)
				elseif v966 == "High Rank Admin" then
					Execute_Commands(t34.Message, "HighRank", FromSpeaker.Name, v966)
				elseif v966 == "Low Rank Admin" then
					Execute_Commands(t34.Message, "LowRank", FromSpeaker.Name, v966)
				elseif v966 == "Goon" then
					Execute_Commands(t34.Message, "LowerRank", FromSpeaker.Name, v966)
				end
			end
		else
			FromSpeaker = t34.FromSpeaker

			if FromSpeaker then
				v966 = GetRank(FromSpeaker, 16168861)

				if v966 == "Leader" then
					Execute_Commands(t34.Message, "Leader", FromSpeaker.Name, v966)

					return
				end

				if v966 == "High Rank Admin" then
					Execute_Commands(t34.Message, "HighRank", FromSpeaker.Name, v966)

					return
				end

				if v966 == "Low Rank Admin" then
					Execute_Commands(t34.Message, "LowRank", FromSpeaker.Name, v966)
				elseif v966 == "Goon" then
					Execute_Commands(t34.Message, "LowerRank", FromSpeaker.Name, v966)
				end
			end
		end
	end
end
