CheckFakeAim = function()
    local CharacterCFrame = GetPlayerCFrame()

    if not CharacterCFrame then
        return smalldiceToyFound
    end

    local Found = 0
    local FoundDistance = math.huge

    for _, Toy in ipairs(v128:GetChildren()) do
        if Toy.Name == "DiceSmall" and Toy.PrimaryPart and Toy:FindFirstChild("Center") then
            local Distance = Getdistancefromcharacter(Toy.PrimaryPart.Position)

            if Distance <= 30 then
                if Distance < FoundDistance then
                    Found = Toy
                    FoundDistance = Distance
                end
            else
                DeleteToyRE:FireServer(Toy)
            end
        end
    end

    if not Found then
        local Position = CharacterCFrame.Position
        local Spawned = false

        pcall(function()
            SpawnToy({
                "DiceSmall",
                CFrame.new(
                    Position.X,
                    Position.Y,
                    Position.Z,
                    -0.133750245,
                    -0.471861839,
                    0.871468484,
                    -3.7252903e-09,
                    0.879369617,
                    0.476139903,
                    -0.991015136,
                    0.0636838302,
                    -0.117615893
                ),
                Vector3.new(0, 97.69000244140625, 0)
            }, _G.HouseBreaked)

            Spawned = true
        end)

        if not Spawned then
            smalldiceToyFound = 0
            return nil
        end
    end

    if Found and not Found:GetAttribute("Connected2") then
        local Dice = Found
        local SoundPart = Dice:FindFirstChild("SoundPart")

        Dice:SetAttribute("Connected2", true)

        local Connection = Dice.DescendantAdded:Connect(function(Descendant)
            if Descendant.Name == "PartOwner" and Descendant.Value ~= LocalPlayer.Name then
                Dice:SetAttribute("AlreadySetOwnerShip", false)
            end
        end)

        task.spawn(function()
            while Dice.Parent and smalldiceToyFound == Dice do
                if not Dice:GetAttribute("AlreadySetOwnerShip") then
                    local Alive = SoundPart and SoundPart.Parent ~= 0

                    if Alive and SNOWshipOnce(SoundPart) then
                        Dice:SetAttribute("AlreadySetOwnerShip", true)
                    else
                        local Pivot = Dice.PrimaryPart and Dice.PrimaryPart.Position or select(1, Dice:GetPivot().Position)

                        if Getdistancefromcharacter(Pivot) > 30 then
                            DeleteToyRE:FireServer(Dice)
                            break
                        end
                    end
                end

                if not _G.FireworkEffectSpam then
                    break
                end

                task.wait(0.1)
            end

            if Connection then
                Connection:Disconnect()
            end

            if smalldiceToyFound == Dice then
                smalldiceToyFound = 0
            end

            print("Pew!")
        end)
    end

    smalldiceToyFound = Found

    return Found
end

